      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = /^\/?[^/]*/.exec(input)[0]
      input = input.slice(match.length)
      output += match
    }
  }
  return output
