    t.hasScheme = true
    t.scheme = base.scheme
    t.hasAuthority = true
    t.hasUserinfo = ref.hasUserinfo
    t.userinfo = ref.userinfo
    t.host = ref.host
    t.hasPort = ref.hasPort
    t.port = ref.port
    t.path = removeDotSegments(ref.path)
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  } else {
    t.hasScheme = true
    t.scheme = base.scheme
    t.hasAuthority = base.hasAuthority
    t.hasUserinfo = base.hasUserinfo
    t.userinfo = base.userinfo
    t.host = base.host
    t.hasPort = base.hasPort
    t.port = base.port

